// PortableApps.com - portable manifest demo
var M = { runtime: "PortableApps", carries: "400+ portable apps", from: "USB stick", size: "varies" };
console.log("Portable runtime: " + M.runtime);
console.log("Carries: " + M.carries);
console.log("Runs from: " + M.from + " | Size: " + M.size);
var files = ["app.exe", "data/", "config.ini"];
console.log("Manifest: " + files.join(", "));
console.log("Host writes required: 0 -> PORTABLE PASS");

